        people_series.extend(s.get("peopleCount", []))

    def aggregate(points: List[Dict]) -> List[Dict]:
        grouped: Dict[str, List[float]] = defaultdict(list)
        for p in points:
            ts = p.get("timestamp") or utc_now()
            grouped[str(ts)].append(to_float(p.get("value"), 0.0))
