    logging.basicConfig(level=os.environ.get("LOG_LEVEL", "INFO"))

CACHE_TTL_SECONDS = 30
query_cache: Dict[Tuple[str, str], Tuple[float, object]] = {}
query_cache_lock = Lock()
    jsonify,
    make_response,
    render_template,
    request,
    send_file,
)
