    if (search) {
      const haystack = [c.name, c.type, c.status, c.code].join(' ').toLowerCase();
      if (!haystack.includes(search)) return false;
    }
    return true;
  });

  const grid = document.getElementById('centersGrid');
  grid.innerHTML = data.length
    ? data
        .map(
          (c) => `
      <article class="card fade-up center-card" id="card-${c.code}">
        <img class="center-card-image" src="${escapeHtml(c.image)}" alt="${escapeHtml(c.name)}" />
        <div style="margin-top:10px;display:flex;justify-content:space-between;align-items:center;gap:8px">
          <h3 style="margin:0">${escapeHtml(c.name)}</h3>
          ${statusBadge(c.status)}
        </div>
        <p class="small">${escapeHtml(c.type)}</p>
        <div class="grid grid-2">
          <div>${tr('temperature')}: <strong>${formatMetric(c.snapshot.avgTemperature, { unit: '°C' })}</strong></div>
          <div>${tr('humidity')}: <strong>${formatMetric(c.snapshot.avgHumidity, { unit: '%' })}</strong></div>
          <div>${tr('co2')}: <strong>${formatMetric(c.snapshot.avgCo2, { digits: 0, unit: 'ppm' })}</strong></div>
          <div>${tr('occupancy')}: <strong>${formatMetric(c.snapshot.avgOccupancy, { digits: 0, unit: '%', zeroAsMissing: false })}</strong></div>
        </div>
        <div class="chart-wrap" style="margin-top:10px;height:170px"><canvas id="spark-${c.code}"></canvas></div>
        <div style="display:flex;justify-content:flex-end;margin-top:10px">
          <a class="btn btn-primary" href="/centers/${c.code}">${tr('viewDetail')}</a>
        </div>
      </article>
    `
        )
        .join('')
    : `<div class="card"><div class="small">${tr('noDataAvailable')}</div></div>`;
}

async function renderSparklines() {
  sparklineCharts.forEach((chart) => chart.destroy());
  sparklineCharts.clear();

  const jobs = centersCache.map(async (c) => {
    try {
      const trend = await apiGet(`/api/centers/${c.code}/trend?range=1h`);
      const ctx = document.getElementById(`spark-${c.code}`);
      if (!ctx) return;

      const tempSeries = (trend.temperature || []).slice(-20);
      const peopleSeries = (trend.peopleCount || []).slice(-20);
      const labelsSource = tempSeries.length ? tempSeries : peopleSeries;
      if (!labelsSource.length) {
        const wrap = ctx.parentElement;
        if (wrap) {
          wrap.innerHTML = `<div class="empty-state">${tr('noDataAvailable')}</div>`;
        }
        return;
      }

      const labels = labelsSource.map((point) => formatTimestampLabel(point.timestamp));
      const temp = labelsSource.map((point) => {
        const match = tempSeries.find((item) => item.timestamp === point.timestamp);
        return match ? Number(match.value) : null;
      });
      const people = labelsSource.map((point) => {
        const match = peopleSeries.find((item) => item.timestamp === point.timestamp);
        return match ? Number(match.value) : null;
      });

      const chart = new Chart(ctx, {
        type: 'line',
        data: {
          labels,
          datasets: [
            {
              label: tr('temperatureWithUnit'),
              data: temp,
              borderColor: '#0e7c74',
              backgroundColor: '#0e7c741a',
              borderWidth: 2,
              fill: true,
              pointRadius: 0,
              tension: 0.25,
              unit: '°C',
            },
            {
              label: tr('occupancyWithUnit'),
              data: people,
              borderColor: '#d27d3f',
              backgroundColor: '#d27d3f1a',
              borderWidth: 2,
              fill: false,
              pointRadius: 0,
              tension: 0.25,
              unit: tr('occupancy'),
            },
          ],
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
            legend: { position: 'bottom' },
            tooltip: {
              callbacks: {
                label(context) {
                  const unit = context.dataset.unit || '';
                  return `${context.dataset.label}: ${formatMetric(context.parsed.y, { digits: 1, unit, zeroAsMissing: false })}`;
                },
              },
            },
          },
          scales: {
            x: {
              title: { display: true, text: 'HH:MM' },
            },
            y: {
              title: { display: true, text: tr('temperature') },
            },
          },
        },
      });
      sparklineCharts.set(c.code, chart);
    } catch (err) {
      console.error(err);
    }
  });
  await Promise.all(jobs);
}

function wireFilters() {
  ['filterType', 'filterStatus', 'filterOccupancy', 'filterSearch'].forEach((id) => {
    document.getElementById(id).addEventListener('change', () => {
      renderCenters();
      renderSparklines();
    });
    document.getElementById(id).addEventListener('input', () => {
      renderCenters();
      renderSparklines();
    });
  });
}

document.addEventListener('DOMContentLoaded', () => {
  if (document.body.getAttribute('data-page') !== 'centers') return;
  wireFilters();
  loadCenters().catch((err) => console.error(err));
  ensureSocket().on('update', () => loadCenters());
});

@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;700&family=Literata:opsz,wght@7..72,500;7..72,700&display=swap');

:root {
  --font-ui: 'Space Grotesk', sans-serif;
  --font-display: 'Literata', serif;

  --bg: #f2efe8;
  --panel: #fff9ef;
  --text: #1d2627;
  --muted: #516266;
  --accent: #0e7c74;
  --accent-2: #d27d3f;
  --danger: #b5443c;
  --warn: #a86b18;
  --ok: #26875f;

  --border: #d7cfbe;
  --shadow: 0 10px 30px rgba(29, 38, 39, 0.12);
  --radius: 14px;
}

[data-theme="dark"] {
  --bg: #101919;
  --panel: #172323;
  --text: #e9f0ec;
  --muted: #99ada7;
  --accent: #45c5bb;
  --accent-2: #f0a15d;
  --danger: #ea7164;
  --warn: #f0bb62;
  --ok: #51d494;

  --border: #28403e;
  --shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: var(--font-ui);
  color: var(--text);
  background:
    radial-gradient(circle at 8% 12%, rgba(14, 124, 116, 0.18) 0, transparent 30%),
    radial-gradient(circle at 92% 6%, rgba(210, 125, 63, 0.16) 0, transparent 35%),
    linear-gradient(180deg, var(--bg), color-mix(in srgb, var(--bg) 88%, #000 12%));
  min-height: 100vh;
}

a {
  color: inherit;
  text-decoration: none;
}

.app-shell {
  width: min(1320px, 94vw);
  margin: 18px auto 28px;
}

.topbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 14px 18px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: color-mix(in srgb, var(--panel) 94%, transparent);
  backdrop-filter: blur(8px);
  box-shadow: var(--shadow);
  position: sticky;
  top: 10px;
  z-index: 20;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
}

.brand-mark {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  background: linear-gradient(145deg, var(--accent), var(--accent-2));
  box-shadow: 0 4px 18px color-mix(in srgb, var(--accent) 55%, transparent);
}

.brand h1 {
  margin: 0;
  font-family: var(--font-display);
  font-size: 1.2rem;
  letter-spacing: 0.02em;
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.btn,
select,
input,
textarea {
  font: inherit;
}

.btn {
  border: 1px solid var(--border);
  background: var(--panel);
  color: var(--text);
  padding: 8px 12px;
  border-radius: 10px;
  cursor: pointer;
  transition: transform 0.2s ease, background 0.2s ease;
}

.btn:hover {
  transform: translateY(-1px);
}

.btn-primary {
  background: linear-gradient(145deg, var(--accent), color-mix(in srgb, var(--accent) 70%, #fff 30%));
  color: #fff;
  border: none;
}

.nav-links {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.nav-link {
  padding: 6px 10px;
  border-radius: 8px;
  border: 1px solid transparent;
  color: var(--muted);
}

.nav-link.active,
.nav-link:hover {
  border-color: var(--border);
  color: var(--text);
  background: color-mix(in srgb, var(--accent) 8%, var(--panel));
}

.grid {
  display: grid;
  gap: 14px;
}

.grid-2 {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.grid-3 {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.grid-4 {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.card {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 14px;
  box-shadow: var(--shadow);
}

.card h2,
.card h3,
.card h4 {
  font-family: var(--font-display);
  margin-top: 0;
}

.kpi {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.kpi .value {
  font-size: 1.55rem;
  font-weight: 700;
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.82rem;
  border-radius: 999px;
  padding: 3px 10px;
  border: 1px solid transparent;
}

.badge.optimal {
  color: var(--ok);
  background: color-mix(in srgb, var(--ok) 13%, transparent);
}

.badge.attention {
  color: var(--warn);
  background: color-mix(in srgb, var(--warn) 13%, transparent);
}

.badge.critical {
  color: var(--danger);
  background: color-mix(in srgb, var(--danger) 13%, transparent);
}

.table-wrap {
  overflow: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th,
td {
  border-bottom: 1px solid var(--border);
  padding: 8px;
  text-align: left;
  font-size: 0.92rem;
}

th {
  color: var(--muted);
  font-weight: 500;
}

.leaflet-map,
.chart-wrap,
.three-wrap,
.grafana-frame {
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
  background: color-mix(in srgb, var(--panel) 96%, #000 4%);
}

.leaflet-map {
  height: 420px;
}

.chart-wrap {
  min-height: 260px;
  padding: 10px;
}

.three-wrap {
  height: 520px;
}

.grafana-frame {
  height: 460px;
}

iframe {
  width: 100%;
  height: 100%;
  border: none;
}

.alert-list {
  max-height: 360px;
  overflow: auto;
  display: grid;
  gap: 8px;
}

.alert-item {
  border: 1px solid var(--border);
  border-left: 5px solid var(--warn);
  border-radius: 10px;
  padding: 8px;
  background: color-mix(in srgb, var(--panel) 92%, #fff 8%);
}

.alert-item.critical {
  border-left-color: var(--danger);
}

.alert-item.optimal {
  border-left-color: var(--ok);
}

.fade-up {
  animation: fadeUp 0.45s ease both;
}

.stagger > * {
  opacity: 0;
  transform: translateY(10px);
  animation: fadeUp 0.4s ease forwards;
}

.stagger > *:nth-child(1) { animation-delay: 0.02s; }
.stagger > *:nth-child(2) { animation-delay: 0.06s; }
.stagger > *:nth-child(3) { animation-delay: 0.1s; }
.stagger > *:nth-child(4) { animation-delay: 0.14s; }
.stagger > *:nth-child(5) { animation-delay: 0.18s; }
.stagger > *:nth-child(6) { animation-delay: 0.22s; }

@keyframes fadeUp {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.controls-row {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  align-items: center;
}

.center-card {
  display: flex;
  flex-direction: column;
}

.center-card-image {
  width: 100%;
  height: 200px;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  object-position: center;
  border-radius: 12px 12px 10px 10px;
  display: block;
}

.input,
select,
textarea {
  border: 1px solid var(--border);
  border-radius: 9px;
  background: var(--panel);
  color: var(--text);
  padding: 8px 10px;
}

.split {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 14px;
}

.pill {
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 4px 10px;
  color: var(--muted);
  font-size: 0.84rem;
}

.meter {
  width: 100%;
  height: 10px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--panel) 82%, #000 18%);
  overflow: hidden;
}

.meter span {
  display: block;
  height: 100%;
  border-radius: inherit;
}

.empty-state {
  min-height: 140px;
  display: grid;
  place-items: center;
  color: var(--muted);
  border: 1px dashed var(--border);
  border-radius: 12px;
  background: color-mix(in srgb, var(--panel) 88%, transparent);
}

.center-popup-wrap .leaflet-popup-content {
  margin: 10px 12px;
}

.grafana-frame + .grafana-link,
.grafana-link {
  display: inline-flex;
  margin-top: 10px;
}

.small {
  font-size: 0.83rem;
  color: var(--muted);
}

.visitor-shell {
  width: min(760px, 94vw);
  margin: 18px auto;
}

.chat-box {
  display: grid;
  gap: 8px;
  max-height: 260px;
  overflow: auto;
  padding: 8px;
  border: 1px solid var(--border);
  border-radius: 12px;
}

.chat-msg {
  border-radius: 10px;
  padding: 8px 10px;
  background: color-mix(in srgb, var(--accent) 10%, var(--panel));
}

.chat-msg.bot {
  background: color-mix(in srgb, var(--accent-2) 16%, var(--panel));
}

@media (max-width: 1024px) {
  .grid-4 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .split {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 720px) {
  .app-shell {
    width: 96vw;
  }

  .topbar {
    position: static;
    padding: 12px;
  }

  .grid-3,
  .grid-2,
  .grid-4 {
    grid-template-columns: 1fr;
  }

  .leaflet-map {
    height: 320px;
  }

  .three-wrap {
    height: 380px;
  }
}

let gaugeCharts = {};
let historyChart;

function centerCodeFromPath() {
  const parts = window.location.pathname.split('/').filter(Boolean);
  return parts[1];
}

function gaugeConfig(value, max, color) {
  return {
    type: 'doughnut',
    data: {
      labels: ['value', 'rest'],
      datasets: [
        {
          data: [Math.max(0, Math.min(max, value)), Math.max(0, max - value)],
          backgroundColor: [color, '#d8d8d833'],
          borderWidth: 0,
          cutout: '72%',
        },
      ],
    },
    options: {
      plugins: { legend: { display: false }, tooltip: { enabled: false } },
      responsive: true,
      maintainAspectRatio: false,
    },
  };
}

function upsertGauge(id, value, max, color, label) {
  const ctx = document.getElementById(id);
  if (!ctx) return;
  if (gaugeCharts[id]) gaugeCharts[id].destroy();
  gaugeCharts[id] = new Chart(ctx, gaugeConfig(value, max, color));
  document.getElementById(`${id}-value`).textContent = `${formatMetric(value, { digits: 1, zeroAsMissing: true })} ${label}`;
}

async function loadCenterSnapshot(code) {
  const center = await apiGet(`/api/centers/${code}`);
  const snap = center.snapshot;
  document.getElementById('centerTitle').textContent = center.name;
  document.getElementById('centerStatus').innerHTML = statusBadge(snap.status);

  upsertGauge('gTemp', snap.avgTemperature, 35, '#0e7c74', '°C');
  upsertGauge('gHum', snap.avgHumidity, 100, '#3d9ecf', '%');
  upsertGauge('gCo2', snap.avgCo2, 1800, '#d27d3f', 'ppm');
  upsertGauge('gNoise', snap.avgNoise, 100, '#7c5bd6', 'dB');
  upsertGauge('gOcc', snap.avgOccupancy ? snap.avgOccupancy * 100 : null, 100, '#a86b18', '%');
}

async function loadRooms(code) {
  const rooms = await apiGet(`/api/centers/${code}/rooms`);
  const list = document.getElementById('roomsList');
  list.innerHTML = rooms
    .map(
      (r) => `
      <div class="card" style="padding:10px">
        <div style="display:flex;justify-content:space-between;gap:8px;align-items:center">
          <strong>${escapeHtml(r.name)}</strong>
          ${statusBadge(r.status)}
        </div>
        <div class="small">${tr('occupancy')}: ${formatMetric(Number(r.current.occupancy || 0) * 100, { digits: 0, unit: '%', zeroAsMissing: false })}</div>
        <a class="btn" href="/room/${encodeURIComponent(r.id)}" style="margin-top:8px">${tr('viewDetail')}</a>
      </div>
    `
    )
    .join('');
}

async function loadRiskArtworks(code) {
  const arts = await apiGet(`/api/centers/${code}/artworks/at-risk`);
  const list = document.getElementById('riskList');
  list.innerHTML = arts.length
    ? arts
        .slice(0, 12)
        .map(
          (a) => `<div class="alert-item ${Number(a.degradationRisk) > 0.8 ? 'critical' : ''}"><strong>${escapeHtml(a.name)}</strong><br/><span class="small">${escapeHtml(a.artist || '')} · ${tr('severity')} ${formatMetric(a.degradationRisk, { digits: 3, zeroAsMissing: false })}</span></div>`
        )
        .join('')
    : `<div class="small">${tr('noDataAvailable')}</div>`;
}

async function loadHistory(code) {
  const range = document.getElementById('rangeSelect').value;
  const history = await apiGet(`/api/centers/${code}/history?range=${range}`);
  const labels = history.temperature.map((p) => formatTimestampLabel(p.timestamp));

  const dataSets = [
    { key: 'temperature', color: '#0e7c74', label: tr('temperature') },
    { key: 'relativeHumidity', color: '#3d9ecf', label: tr('humidity') },
    { key: 'co2', color: '#d27d3f', label: tr('co2') },
    { key: 'LAeq', color: '#7c5bd6', label: 'LAeq' },
    { key: 'peopleCount', color: '#a86b18', label: tr('occupancy') },
  ];

  const datasets = dataSets.map((s) => ({
    label: s.label,
    data: history[s.key].map((p) => (p.value === null || p.value === undefined ? null : Number(p.value))),
    borderColor: s.color,
    backgroundColor: `${s.color}22`,
    fill: false,
    tension: 0.2,
    pointRadius: 0,
  }));

  if (historyChart) historyChart.destroy();
  historyChart = new Chart(document.getElementById('historyChart'), {
    type: 'line',
    data: { labels, datasets },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: { position: 'bottom' },
        tooltip: {
          callbacks: {
            label(context) {
              return `${context.dataset.label}: ${formatMetric(context.parsed.y, { digits: 1, zeroAsMissing: false })}`;
            },
          },
        },
      },
    },
  });
}

async function loadActuators(code) {
  const acts = await apiGet(`/api/centers/${code}/actuators`);
  const wrap = document.getElementById('actuatorPanel');
  wrap.innerHTML = acts
    .map(
      (a) => `
      <div class="card" style="padding:10px">
        <div style="display:flex;justify-content:space-between;align-items:center;gap:8px">
          <strong>${a.name || a.id}</strong>
          <span class="pill">${a.status || 'off'}</span>
        </div>
        <div class="controls-row" style="margin-top:8px">
          <button class="btn btn-primary" data-act="${a.id}" data-cmd="on">ON</button>
          <button class="btn" data-act="${a.id}" data-cmd="off">OFF</button>
        </div>
      </div>
    `
    )
    .join('');

  wrap.querySelectorAll('button[data-act]').forEach((btn) => {
    btn.addEventListener('click', async () => {
      const id = btn.getAttribute('data-act');
      const cmd = btn.getAttribute('data-cmd');
      await apiSend(`/api/actuators/${encodeURIComponent(id)}/command`, 'POST', { command: cmd });
      await loadActuators(code);
    });
  });
}

async function loadGrafana(code) {
  const info = await apiGet(`/api/grafana/center/${code}`);
  document.getElementById('grafanaFrame').src = info.embed;
}

async function bootCenterDetail() {
  const code = centerCodeFromPath();
  await Promise.all([
    loadCenterSnapshot(code),
    loadRooms(code),
    loadRiskArtworks(code),
    loadHistory(code),
    loadActuators(code),
    loadGrafana(code),
  ]);

  document.getElementById('rangeSelect').addEventListener('change', () => loadHistory(code));

  const socket = ensureSocket();
  socket.on('update', () => loadCenterSnapshot(code));
  socket.on('actuators', () => loadActuators(code));
  socket.on('alerts', () => loadRiskArtworks(code));
}

document.addEventListener('DOMContentLoaded', () => {
  if (document.body.getAttribute('data-page') !== 'center-detail') return;
  bootCenterDetail().catch((err) => console.error(err));
});

function poiFromPath() {
  const parts = window.location.pathname.split('/').filter(Boolean);
  return decodeURIComponent(parts[1]);
}

function airBadge(status) {
  if (status === 'excellent') return '<span class="badge optimal">Aire excelente</span>';
  if (status === 'acceptable') return '<span class="badge attention">Aire aceptable</span>';
  return '<span class="badge critical">Aire mejorable</span>';
}

async function loadVisitorData() {
  const poi = poiFromPath();
  const [summary, recommended] = await Promise.all([
    apiGet(`/api/public/poi/${encodeURIComponent(poi)}/summary`),
    apiGet(`/api/public/poi/${encodeURIComponent(poi)}/recommended-room`),
  ]);

  document.getElementById('visitorTitle').textContent = summary.center.name;
  document.getElementById('airStatus').innerHTML = airBadge(summary.airStatus);
  document.getElementById('co2Val').textContent = formatMetric(summary.snapshot.avgCo2, { digits: 0, unit: 'ppm' });
  document.getElementById('tempVal').textContent = formatMetric(summary.snapshot.avgTemperature, { unit: '°C' });
  document.getElementById('humVal').textContent = formatMetric(summary.snapshot.avgHumidity, { unit: '%' });
  document.getElementById('occVal').textContent = formatMetric(summary.snapshot.avgOccupancy, { digits: 0, unit: '%', zeroAsMissing: false });

  if (recommended && recommended.room) {
    document.getElementById('recommendedRoom').textContent =
      `Recomendación: ${recommended.room.name} (índice ${formatMetric(recommended.comfortIndex, { digits: 1, zeroAsMissing: false })})`;
  }
}

function appendChat(role, text) {
  const box = document.getElementById('chatBox');
  const el = document.createElement('div');
  el.className = `chat-msg ${role}`;
  el.textContent = text;
  box.appendChild(el);
  box.scrollTop = box.scrollHeight;
}

async function askChat() {
  const poi = poiFromPath();
  const input = document.getElementById('chatInput');
  const question = input.value.trim();
  if (!question) return;

  appendChat('user', question);
  input.value = '';

  try {
    const start = performance.now();
    const res = await apiSend('/api/public/chat/ask', 'POST', {
      poi_id: poi,
      question,
      language: AURA.lang,
    });
    const elapsed = Math.round(performance.now() - start);
    appendChat('bot', `${res.answer} (${elapsed} ms)`);
  } catch (err) {
    appendChat('bot', 'No ha sido posible responder ahora mismo.');
  }
}

function wireChat() {
  document.getElementById('chatSend').addEventListener('click', askChat);
  document.getElementById('chatInput').addEventListener('keydown', (e) => {
    if (e.key === 'Enter') askChat();
  });
}

